    result = []
    for item in words:
        # Split by space and check each word
        sub_words = item.split()
        for w in sub_words:
            if w.startswith('P'):  # Case-sensitive based on example
                result.append(w)
            elif w.lower().startswith('p'): # Handle lowercase if needed
                result.append(w)

        if len(result) >= 2:
